    # [MIGRATION]: Instantiate EcosystemHub facade from elite_ecosystem.py
    from .agents.elite_ecosystem import EcosystemHub
    ecosystem_hub = EcosystemHub(ai_handler=ai_handler, ws_broadcast=ws_broadcast)
