app = FastAPI(
    title="Makima Brain",
    version="7.1.0",
    description="Makima v7.1 AI Desktop Assistant",
    lifespan=lifespan,
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/health")
async def health_check():
    """Quick health check endpoint."""
    health: Any = _modules.get("health")
    if health:
        ok = health.is_critical_path_ok()
        return {"status": "ok" if ok else "degraded", "version": "7.1.0"}
    return {"status": "starting", "version": "7.1.0"}


@app.get("/status")
async def full_status():
    """Full service health snapshot."""
    health: Any = _modules.get("health")
    watchdog: Any = _modules.get("watchdog")
    orchestrator: Any = _modules.get("orchestrator")
    ollama: Any = _modules.get("ollama")

    snapshot = {}
    if health:
        snapshot["services"] = {
            k: {"status": v.status, "error": v.error}
            for k, v in health.get_snapshot().items()
        }
    if watchdog:
        snapshot["native_services"] = watchdog.get_status()
    if orchestrator:
        snapshot["agents"] = orchestrator.get_status()
    if ollama:
        snapshot["local_models"] = await ollama.list_models()

    return JSONResponse(content=snapshot)


@app.get("/conversations")
async def list_conversations():
    memory = _modules.get("memory")
    return {"conversations": await memory.list_conversations() if memory else []}


@app.get("/conversations/{conversation_id}")
async def get_conversation(conversation_id: str):
    memory = _modules.get("memory")
    return {"messages": await memory.get_conversation(conversation_id) if memory else []}


@app.delete("/conversations/{conversation_id}")
async def delete_conversation(conversation_id: str):
    memory = _modules.get("memory")
    if not memory:
        return {"status": "error", "message": "Memory offline"}
    success = await memory.delete_conversation(conversation_id)
    router = _modules.get("router")
    if router and hasattr(router, "cleanup_conversation"):
        router.cleanup_conversation(conversation_id)
    return {"status": "ok" if success else "error"}


@app.get("/integrations")
async def integrations_status():
    health = _modules.get("health")
    store = _modules.get("settings_store")
    services = health.get_snapshot() if health else {}
    result = []
    for name, value in services.items():
        entry = {"id": name, "status": value.status, "error": value.error}
        if store:
            entry["configured"] = store.has_integration_configured(name)
            entry["fields"] = store.get_integration_fields(name)
        result.append(entry)
    return {"integrations": result}


@app.post("/integrations/{integration_id}")
async def save_integration(integration_id: str, request: Request):
    """
    Persists integration credentials to disk (configs/user_settings.json).
    Does NOT hot-reload the running MessagingHub/etc -- those read config
    once at startup, so this takes effect on the next brain restart. The
    response says so explicitly rather than implying an instant connection.
    """
    store = _modules.get("settings_store")
    if not store:
        return {"ok": False, "error": "Settings store not available."}
    payload = await request.json()
    fields = payload.get("fields", {})
    if not isinstance(fields, dict):
        return {"ok": False, "error": "'fields' must be an object."}
    store.save_integration_fields(integration_id, fields)
    return {
        "ok": True,
        "message": "Saved. Restart the Makima brain for this to take effect.",
        "fields": store.get_integration_fields(integration_id),
    }


@app.post("/integrations/{integration_id}/test")
async def test_integration(integration_id: str):
    """
    Best-effort live connectivity test using the currently SAVED (not the
    running) credentials, since save doesn't hot-reload the live service.
    Currently implements a real test for Telegram (simple getMe call);
    other integrations report "not yet implemented" honestly rather than
    faking a pass.
    """
    store = _modules.get("settings_store")
    if not store:
        return {"ok": False, "message": "Settings store not available."}

    raw = store.get_integration_raw(integration_id)

    if integration_id == "telegram":
        token = raw.get("bot_token", "")
        if not token:
            return {"ok": False, "message": "No bot token saved yet."}
        try:
            import httpx
            async with httpx.AsyncClient(timeout=10.0, verify=False) as client:
                resp = await client.get(f"https://api.telegram.org/bot{token}/getMe")
            data = resp.json()
            if data.get("ok"):
                bot_name = data.get("result", {}).get("username", "unknown")
                return {"ok": True, "message": f"Connected as @{bot_name}"}
            return {"ok": False, "message": data.get("description", "Telegram rejected the token.")}
        except Exception as e:
            return {"ok": False, "message": f"Connection test failed: {e}"}

    if not raw or not any(raw.values()):
        return {"ok": False, "message": "No credentials saved yet for this integration."}
    return {"ok": False, "message": f"Live test not yet implemented for '{integration_id}' -- credentials are saved though."}


# ---------------------------------------------------------------------------
# OAuth 2.0 Routes
# ---------------------------------------------------------------------------

# Singleton OAuthManager — initialised lazily on first request
_oauth_manager: Any = None


def _get_oauth() -> Any:
    global _oauth_manager
    if _oauth_manager is None:
        from .auth.oauth_manager import OAuthManager
        _oauth_manager = OAuthManager()
    return _oauth_manager


@app.get("/auth/login/{provider}")
async def oauth_login(provider: str):
    """
    Redirect the user's browser to the provider's OAuth login page.
    Generates a PKCE challenge for Google; state CSRF protection for GitHub.
    """
    from fastapi.responses import RedirectResponse
    try:
        url = _get_oauth().get_auth_url(provider)
        return RedirectResponse(url=url)
    except ValueError as ve:
        return JSONResponse(status_code=400, content={"error": str(ve)})
    except EnvironmentError as ee:
        return JSONResponse(status_code=503, content={"error": str(ee)})
    except Exception as exc:
        logger.error("[auth] /auth/login/%s error: %s", provider, exc)
        return JSONResponse(status_code=500, content={"error": "Internal error starting OAuth flow."})


@app.get("/auth/callback")
async def oauth_callback(code: str = "", state: str = "", error: str = ""):
    """
    OAuth callback endpoint. The provider redirects here after the user
    approves/denies access. Exchanges the code for tokens and saves them.
    Serves a self-closing HTML page so the user can return to Makima.
    """
    from fastapi.responses import HTMLResponse
    if error:
        logger.warning("[auth] OAuth callback received error: %s", error)
        html = f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">
        <title>Makima — Connection Failed</title>
        <style>body{{font-family:system-ui;background:#0f0f1a;color:#f87171;
        display:flex;align-items:center;justify-content:center;height:100vh;margin:0}}
        .card{{text-align:center;padding:40px 60px;border:1px solid #7f1d1d;
        border-radius:16px;background:#1a0a0a}}</style></head><body>
        <div class="card"><h1>✗ Connection Failed</h1><p>{error}</p>
        <script>setTimeout(()=>window.close(),4000);</script></div></body></html>"""
        return HTMLResponse(content=html, status_code=400)

    if not code or not state:
        return JSONResponse(status_code=400, content={"error": "Missing code or state parameter."})

    html = await _get_oauth().handle_callback(code, state)
    return HTMLResponse(content=html)


@app.get("/auth/status")
async def oauth_status():
    """Returns connection status for all known OAuth providers."""
    return {"providers": _get_oauth().status()}


@app.delete("/auth/disconnect/{provider}")
async def oauth_disconnect(provider: str):
    """Removes stored tokens for the given provider (disconnects the app)."""
    try:
        _get_oauth().disconnect(provider)
        return {"ok": True, "message": f"Disconnected from {provider}."}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


@app.get("/settings")
async def settings_snapshot():
    speech = _modules.get("speech")
    ollama = _modules.get("ollama")
    store = _modules.get("settings_store")
    return {
        "voice": {"wake_word_enabled": getattr(speech, "wake_word_enabled", False), "ptt_key": getattr(speech, "ptt_key", "")},
        "ollama": {"default_model": getattr(ollama, "default_model", "")},
        "general": store.get_settings() if store else {},
    }


@app.post("/settings")
async def update_settings(request: Request):
    payload = await request.json()
    speech = _modules.get("speech")
    store = _modules.get("settings_store")
    if speech:
        if "wake_word_enabled" in payload: await speech.set_wake_word_enabled(bool(payload["wake_word_enabled"]))
        if "ptt_key" in payload: speech.ptt_key = str(payload["ptt_key"])
    if store:
        # Everything else (privacy_mode, backup_path, llm backend toggles,
        # etc.) goes into the general persisted-settings bucket. Some of
        # these (privacy_mode especially) only take effect on next restart
        # -- see user_settings_store.py's module docstring for why.
        general_keys = {k: v for k, v in payload.items() if k not in ("wake_word_enabled", "ptt_key")}
        if general_keys:
            store.update_settings(general_keys)
    return await settings_snapshot()

@app.websocket("/ws")
async def websocket_endpoint(ws: WebSocket):
    """Main WebSocket endpoint ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â all UIÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂBrain communication flows here."""
    global _ws_clients
    await ws.accept()
    _ws_clients.add(ws)
    logger.info(f"WS client connected. Total: {len(_ws_clients)}")

    from .ws_protocol import WSMessage, ClientMessageType, generate_task_id, build_ai_chunk

    try:
        while True:
            raw = await ws.receive_text()
            try:
                msg = WSMessage.from_json(raw)
            except Exception as e:
                await ws.send_text(f'{{"error": "Invalid message: {e}"}}')
                continue

            await _handle_ws_message(msg, ws)

    except WebSocketDisconnect:
        logger.info("WS client disconnected.")
    except Exception as e:
        logger.error(f"WS error: {e}")
    finally:
        _ws_clients.discard(ws)


async def _handle_ws_message(msg: Any, ws: WebSocket) -> None:
    """Route incoming WS messages to the correct module."""
    from .ws_protocol import (ClientMessageType, generate_task_id,
                               build_ai_chunk, WSMessage, PROTOCOL_VERSION)

    router: Any = _modules.get("router")
    messaging: Any = _modules.get("messaging")

    msg_type = msg.type if hasattr(msg, "type") else ""
    payload = msg.payload if hasattr(msg, "payload") else {}
    task_id = getattr(msg, "task_id", None) or generate_task_id()

    if msg_type == ClientMessageType.USER_MESSAGE.value:
        text = payload.get("text", "").strip()
        if not text:
            return
        context = {"conversation_id": payload.get("conversation_id") or task_id}
        if payload.get("file_name") and payload.get("file_data"):
            multimodal = _modules.get("multimodal")
            if multimodal:
                file_context = await multimodal.process_file(
                    payload["file_name"],
                    payload.get("file_mime", "application/octet-stream"),
                    payload["file_data"],
                )
                context["document"] = file_context
        if router:
            await router.handle_message(task_id, text, context=context)

    elif msg_type == ClientMessageType.CANCEL_TASK.value:
        if router:
            await router.cancel_task(task_id)

    elif msg_type == ClientMessageType.APPROVE_ACTION.value:
        action = payload.get("action", "")
        # Route through BaseAgent pending confirmations first
        from .agents.base_agent import BaseAgent
        agent_confirm_id = f"{task_id}_{action}"
        if await BaseAgent.resolve_confirmation(agent_confirm_id, approved=True):
            await ws_broadcast(build_ai_chunk(task_id, "Approved.", is_final=True))
        elif action == "send_message" and messaging:
            result = await messaging.approve_send(task_id)
            await ws_broadcast(build_ai_chunk(task_id, result, is_final=True))
        elif action == "forget_cascade":
            memory_forget = _modules.get("memory_forget")
            if memory_forget:
                result = await memory_forget.confirm_forget(task_id)
                await ws_broadcast(build_ai_chunk(task_id, result, is_final=True))

    elif msg_type == ClientMessageType.REJECT_ACTION.value:
        action = payload.get("action", "")
        from .agents.base_agent import BaseAgent
        agent_confirm_id = f"{task_id}_{action}"
        if await BaseAgent.resolve_confirmation(agent_confirm_id, approved=False):
            await ws_broadcast(build_ai_chunk(task_id, "Rejected.", is_final=True))
        elif action == "send_message" and messaging:
            result = await messaging.cancel_send(task_id)
            await ws_broadcast(build_ai_chunk(task_id, result, is_final=True))

    elif msg_type == ClientMessageType.FEEDBACK.value:
        learning = _modules.get("learning")
        if learning:
            await learning.record_feedback(
                turn_id=task_id,
                is_positive=payload.get("positive", True),
                category=payload.get("category", "general"),
            )

    elif msg_type in (ClientMessageType.FOCUS_CHANGE.value, ClientMessageType.SET_FOCUS_PROFILE.value):
        focus_profiles = _modules.get("focus_profiles")
        if focus_profiles:
            profile_name = payload.get("profile", "Work")
            toggles = focus_profiles.apply_profile(profile_name)
            # Apply voice toggle
            speech = _modules.get("speech")
            if speech and "wake_word_enabled" in toggles:
                await speech.set_wake_word_enabled(toggles["wake_word_enabled"])
            logger.info(f"Focus profile changed to: {profile_name}")

    elif msg_type == ClientMessageType.PULL_OLLAMA_MODEL.value:
        ollama = _modules.get("ollama")
        if ollama:
            result = await ollama.pull_model(payload.get("model_name", ""))
            await ws_broadcast(build_ai_chunk(task_id, result, is_final=True))

    elif msg_type == ClientMessageType.DELETE_OLLAMA_MODEL.value:
        ollama = _modules.get("ollama")
        if ollama:
            result = await ollama.delete_model(payload.get("model_name", ""))
            await ws_broadcast(build_ai_chunk(task_id, result, is_final=True))

    elif msg_type == ClientMessageType.PTT_DOWN.value:
        speech = _modules.get("speech")
        if speech:
            await speech.handle_ptt_down()

    elif msg_type == ClientMessageType.PTT_UP.value:
        speech = _modules.get("speech")
        if speech:
            audio_b64 = payload.get("audio_data", "")
            import base64
            audio_bytes = base64.b64decode(audio_b64) if audio_b64 else b""
            await speech.handle_ptt_up(audio_bytes)

    elif msg_type == ClientMessageType.STT_CONFIRM.value:
        speech = _modules.get("speech")
        if speech:
            await speech.confirm_transcript(task_id)

    elif msg_type == ClientMessageType.STT_CORRECT.value:
        speech = _modules.get("speech")
        if speech:
            corrected_text = payload.get("corrected_text", "")
            await speech.correct_transcript(task_id, corrected_text)

    elif msg_type == ClientMessageType.STT_CANCEL.value:
        speech = _modules.get("speech")
        if speech:
            await speech.cancel_transcript(task_id)

    else:
        logger.debug(f"Unhandled WS message type: {msg_type}")


